31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "bulk_signup_warning")
69	    private Boolean bulkSignupWarning;
70	
71	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
72	    private Set<Pet> pets;
73	
74	    public String getAddress() {
75	        return this.address;
76	    }
77	
78	    public void setAddress(String address) {
79	        this.address = normalizeAddress(address);
80	    }
81	
82	    public String getCity() {
83	        return this.city;
84	    }
85	
86	    public void setCity(String city) {
87	        this.city = city;
88	    }
89	
90	    public String getTelephone() {
91	        return this.telephone;
92	    }
93	
94	    public void setTelephone(String telephone) {
95	        this.telephone = telephone;
96	    }
97	
98	    public String getEmail() {
99	        return this.email;
100	    }
101	
102	    public void setEmail(String email) {
103	        this.email = normalizeEmail(email);
104	    }
105	
106	    public LocalDate getRegistrationDate() {
107	        return this.registrationDate;
108	    }
109	
110	    public void setRegistrationDate(LocalDate registrationDate) {
111	        this.registrationDate = registrationDate;
112	    }
113	
114	    public String getCustomerCode() {
115	        return this.customerCode;
116	    }
117	
118	    public void setCustomerCode(String customerCode) {
119	        this.customerCode = customerCode;
120	    }
121	
122	    public Integer getNamesakeCount() {
123	        return this.namesakeCount;
124	    }
125	
126	    public void setNamesakeCount(Integer namesakeCount) {
127	        this.namesakeCount = namesakeCount;
128	    }
