130	    public Boolean getBulkSignupWarning() {
131	        return this.bulkSignupWarning;
132	    }
133	
134	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
135	        this.bulkSignupWarning = bulkSignupWarning;
136	    }
