269	    @Override
270	    @Transactional
271	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
272	        boolean isCreate = owner.isNew();
273	        assertTelephoneIsUnique(owner);
274	        if (owner.isNew()) {
275	            assertEmailIsUnique(owner);
276	            assertCityHasCapacity(owner);
277	        }
278	        if (owner.isNew() && !sharesHousehold) {
279	            assertHouseholdIsUnique(owner);
280	        }
281	        if (owner.getRegistrationDate() == null) {
282	            owner.setRegistrationDate(LocalDate.now());
283	        }
284	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
285	        if (owner.isNew()) {
286	            assertDailyRegistrationLimit(owner);
287	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
288	        }
289	        if (owner.isNew() && owner.getCustomerCode() == null) {
290	            owner.setCustomerCode(generateCustomerCode(owner));
291	        }
292	        if (owner.isNew() && owner.getNamesakeCount() == null) {
293	            owner.setNamesakeCount(countNamesakes(owner));
294	        }
295	        ownerRepository.save(owner);
296	        if (isCreate) {
297	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
298	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
299	        }
300	    }
301	
302	    /**
303	     * Count the existing owners that, at the moment this owner is created, share its first name
304	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
305	     * it never counts itself. This value is deterministic given the current data, so it is computed
306	     * once at creation time and stored.
307	     */
308	    private Integer countNamesakes(Owner owner) {
309	        String firstName = owner.getFirstName();
310	        String lastName = owner.getLastName();
311	        if (firstName == null || lastName == null) {
312	            return 0;
313	        }
314	        return (int) ownerRepository.findAll().stream()
315	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
316	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
317	                && lastName.equalsIgnoreCase(existing.getLastName()))
318	            .count();
319	    }
320	
321	    /**
322	     * Build an owner's {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where
323	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} the
324	     * upper-cased first three letters of the last name, and {@code NNNN} a per-city, 4-digit
325	     * zero-padded sequence equal to one more than the number of owners already in that city
326	     * (e.g. {@code 'LON-SMI-0007'}).
327	     */
328	    private String generateCustomerCode(Owner owner) {
329	        String city = owner.getCity();
330	        String city3 = codePrefix(city);
331	        String last3 = codePrefix(owner.getLastName());
332	        long sequence = ownerRepository.findAll().stream()
333	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
334	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
335	            .count() + 1L;
336	        return String.format("%s-%s-%04d", city3, last3, sequence);
337	    }
338	
339	    /**
340	     * Build a {@code customerCode} segment from {@code value}: its first three characters
341	     * (fewer if it is shorter), upper-cased.
342	     */
343	    private static String codePrefix(String value) {
344	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
345	    }
346	
347	    /**
348	     * Enforce that an owner's normalized telephone is not already used by any <em>other</em>
349	     * owner, throwing {@link DuplicateTelephoneException} if it is. The owner being saved is
350	     * excluded by id so updating an owner in place does not conflict with itself.
351	     */
352	    private void assertTelephoneIsUnique(Owner owner) {
353	        String normalized = Owner.normalizeTelephone(owner.getTelephone());
354	        if (normalized == null) {
355	            return;
356	        }
357	        boolean duplicate = ownerRepository.findAll().stream()
358	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
359	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
360	            .anyMatch(normalized::equals);
361	        if (duplicate) {
362	            throw new DuplicateTelephoneException(normalized);
363	        }
364	    }
365	
366	    /**
367	     * Enforce that an owner's lower-cased email is not already used by any <em>other</em> owner,
368	     * throwing {@link DuplicateEmailException} if it is. Emails are compared in their canonical
369	     * lower-cased form (see {@link Owner#normalizeEmail(String)}). The owner being saved is
370	     * excluded by id so it never conflicts with itself.
371	     */
372	    private void assertEmailIsUnique(Owner owner) {
373	        String normalized = Owner.normalizeEmail(owner.getEmail());
374	        if (normalized == null || normalized.isEmpty()) {
375	            return;
376	        }
377	        boolean duplicate = ownerRepository.findAll().stream()
378	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
379	            .map(existing -> Owner.normalizeEmail(existing.getEmail()))
380	            .anyMatch(normalized::equals);
381	        if (duplicate) {
382	            throw new DuplicateEmailException(normalized);
383	        }
384	    }
385	
386	    /**
387	     * Enforce that no <em>other</em> owner already shares this owner's household, i.e. has the same
388	     * last name (compared case-insensitively with collapsed whitespace, see
389	     * {@link Owner#normalizeHousehold(String)}) and the same normalized address (see
390	     * {@link Owner#normalizeAddress(String)}), throwing {@link DuplicateHouseholdException} if one
391	     * does. The owner being saved is excluded by id. Callers skip this check when the request opted
392	     * in with {@code sharesHousehold}.
393	     */
394	    private void assertHouseholdIsUnique(Owner owner) {
395	        String lastName = Owner.normalizeHousehold(owner.getLastName());
396	        String address = Owner.normalizeAddress(owner.getAddress());
397	        if (lastName == null || address == null) {
398	            return;
399	        }
400	        boolean duplicate = ownerRepository.findAll().stream()
401	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
402	            .anyMatch(existing -> lastName.equals(Owner.normalizeHousehold(existing.getLastName()))
403	                && address.equals(Owner.normalizeAddress(existing.getAddress())));
404	        if (duplicate) {
405	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
406	        }
407	    }
408	
409	    /**
410	     * Enforce that the owner's city has not yet reached its capacity, throwing
411	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
412	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
413	     */
414	    private void assertCityHasCapacity(Owner owner) {
415	        String city = owner.getCity();
416	        if (city == null) {
417	            return;
418	        }
419	        long count = ownerRepository.findAll().stream()
420	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
421	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
422	            .count();
423	        if (count >= MAX_OWNERS_PER_CITY) {
424	            throw new CityAtCapacityException(city);
425	        }
426	    }
427	
428	    /**
429	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
430	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
431	     * the effective registration date (whether supplied in the request or defaulted to the server
432	     * date) so that every value derived from it&mdash;such as the membership number's year segment
433	     * and the daily create-limit counting&mdash;uses the adjusted business day.
434	     */
435	    private static LocalDate rollToBusinessDay(LocalDate date) {
436	        if (date == null) {
437	            return null;
438	        }
439	        DayOfWeek dayOfWeek = date.getDayOfWeek();
440	        if (dayOfWeek == DayOfWeek.SATURDAY) {
441	            return date.plusDays(2);
442	        }
443	        if (dayOfWeek == DayOfWeek.SUNDAY) {
444	            return date.plusDays(1);
445	        }
446	        return date;
447	    }
448	
449	    /**
450	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
451	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
452	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
453	     * is excluded by id.
454	     */
455	    private void assertDailyRegistrationLimit(Owner owner) {
456	        LocalDate registrationDate = owner.getRegistrationDate();
457	        if (registrationDate == null) {
458	            return;
459	        }
460	        long count = ownerRepository.findAll().stream()
461	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
462	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
463	            .count();
464	        if (count >= MAX_OWNERS_PER_DAY) {
465	            throw new DailyRegistrationLimitException(registrationDate);
466	        }
467	    }
468	
469	    /**
470	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
471	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
472	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
473	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
474	     * stored on the owner.
475	     */
476	    private boolean computeBulkSignupWarning(Owner owner) {
477	        LocalDate registrationDate = owner.getRegistrationDate();
478	        if (registrationDate == null) {
479	            return false;
480	        }
481	        long count = ownerRepository.findAll().stream()
482	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
483	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
484	            .count();
485	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
486	    }
487	
488	    @Override
489	    @Transactional(readOnly = true)
490	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
491	        return ownerRepository.findByLastName(lastName);
492	    }
493	
494	    @Override
495	    @Transactional(readOnly = true)
496	    public Collection<Visit> findVisitsByPetId(int petId) {
497	        return visitRepository.findByPetId(petId);
498	    }
499	
500	    @Override
501	    @Transactional(readOnly = true)
502	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
503	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
504	    }
505	
506	    private <T> T findEntityById(Supplier<T> supplier) {
507	        try {
508	            return supplier.get();
509	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
510	            // Just ignore not found exceptions for Jdbc/Jpa realization
511	            return null;
512	        }
513	    }
514	
515	}
