248	        HttpStatus status = HttpStatus.BAD_REQUEST;
249	        BindingErrorsResponse errors = new BindingErrorsResponse();
250	        BindingResult bindingResult = e.getBindingResult();
251	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
252	        if (bindingResult.hasErrors()) {
253	            errors.addAllErrors(bindingResult);
254	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
255	                .map(fieldError -> {
256	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
257	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
258	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
259	                        fieldError.getField(),
260	                        defaultMessage,
261	                        rejectedValue);
262	                    return new ValidationMessageDto(message)
263	                        .putAdditionalProperty("field", fieldError.getField())
264	                        .putAdditionalProperty("rejectedValue", rejectedValue)
265	                        .putAdditionalProperty("defaultMessage", defaultMessage);
266	                })
267	                .toList();
268	            logger.debug("Validation error at {} {}: {}",
269	                request.getMethod(),
270	                request.getRequestURI(),
271	                bindingResult.getFieldErrors());
272	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
273	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
274	                .map(FieldError::getField)
275	                .distinct()
276	                .toList();
277	            detail.setProperty("errors", invalidFields);
278	            return ResponseEntity.status(status).body(detail);
279	        }
280	        return ResponseEntity.status(status).body(detail);
281	    }
