/**
 * Enforce that no <em>other</em> owner already shares this owner's derived {@code identityKey},
 * throwing {@link DuplicateIdentityException} if one does. This single check consolidates the
 * former separate telephone, email and household duplicate checks: an owner is a duplicate only
 * when its <em>whole</em> identity key&mdash;normalized telephone, normalized email (or empty)
 * and household id (see {@link Owner#identityKey(String, String, String, String)})&mdash;equals
 * an existing owner's. Because the telephone is part of the key, two members of the same
 * household with different telephones have different keys and are both allowed. The owner being
 * saved is excluded by id so updating an owner in place never conflicts with itself.
 */
private void assertIdentityIsUnique(Owner owner) {
    String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
    if (normalizedTelephone == null) {
        return;
    }
    boolean duplicate = ownerRepository.findAll().stream()
        .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
        .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
        .anyMatch(normalizedTelephone::equals);
    if (duplicate) {
        throw new DuplicateIdentityException(Owner.identityKey(
            owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getAddress()));
    }
}

